import React,{useEffect,useState} from "react";
import {TrendingUp} from "lucide-react";
import api from "../services/api";

export default function Analytics(){
  const [data,setData]=useState(null);
  useEffect(()=>{api.get("/analytics/margin").then(r=>setData(r.data)).catch(()=>{});},[]);
  return <>
    <div className="page-head"><div><span className="eyebrow">BUSINESS INSIGHTS</span><h2>Analytics</h2><p>Understand FPO procurement and sales performance.</p></div></div>
    {data?<div className="panel analytics-box"><div className="analytics-icon"><TrendingUp/></div><h3>Margin overview</h3><div className="json-grid">{Object.entries(data).map(([k,v])=><div key={k}><span>{k.replaceAll("_"," ")}</span><b>{typeof v==="object"?JSON.stringify(v):String(v)}</b></div>)}</div></div>:<div className="empty">Analytics data unavailable for this role.</div>}
  </>;
}
